// dec8b10b: code -> {k, d}; code_err for invalid words, disp_err when the word's disparity
// contradicts the running disparity.
module dec8b10b (
  input  logic [9:0] code,
  input  logic       rd,
  output logic [7:0] d,
  output logic       k,
  output logic       rd_out,
  output logic       code_err,
  output logic       disp_err
);
  logic signed [4:0] dsp;
  always_comb begin
    dsp = 0;
    for (int i = 0; i < 10; i++) dsp = dsp + (code[i] ? 5'sd1 : -5'sd1);
    code_err = 1'b0;
    case (code)
      10'b0001010101: begin d = 8'h57; k = 1'b0; end
      10'b0001010110: begin d = 8'hd7; k = 1'b0; end
      10'b0001010111: begin d = 8'hf7; k = 1'b1; end
      10'b0001011001: begin d = 8'h37; k = 1'b0; end
